<?php
require 'bootstrap.php';$error='';$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 try{
    $id=(int)post('id');$name=post('name');$fee=commerce_money_input(post('fee'));$free=post('free_min')===''?null:commerce_money_input(post('free_min'));$areas=implode("\n",commerce_provinces(post('provinces')));
    if($name===''||mb_strlen($name)>120||mb_strlen($areas)>10000)throw new RuntimeException('ชื่อบริการหรือพื้นที่ไม่ถูกต้อง');
    if($id&&!q('SELECT id FROM shipping_services WHERE id=?',[$id])->fetchColumn())throw new RuntimeException('ไม่พบบริการ');
    $codFee=commerce_money_input(post('cod_fee')?:'0');$eta=post('eta_days');$weight=post('max_weight');if(mb_strlen($eta)>80||($weight!==''&&!preg_match('/^[0-9]{1,6}(?:\.[0-9]{1,3})?$/D',$weight)))throw new RuntimeException('ระยะเวลาหรือน้ำหนักไม่ถูกต้อง');$params=[$name,$fee/100,$free===null?null:$free/100,$areas?:null,isset($_POST['cod_allowed'])?1:0,isset($_POST['active'])?1:0,$codFee/100,$eta,$weight?:null];
    if($id)q('UPDATE shipping_services SET name=?,fee=?,free_min=?,provinces=?,cod_allowed=?,active=?,cod_fee=?,eta_days=?,max_weight=? WHERE id=?',array_merge($params,[$id]));else q('INSERT INTO shipping_services(name,fee,free_min,provinces,cod_allowed,active,cod_fee,eta_days,max_weight) VALUES (?,?,?,?,?,?,?,?,?)',$params);
    flash('บันทึกบริการขนส่งแล้ว คำสั่งซื้อเก่าไม่เปลี่ยน');go('admin/shipping.php');
 }catch(RuntimeException $exception){$error=$exception instanceof PDOException?'บันทึกไม่สำเร็จ':$exception->getMessage();}
}
$service=$id?q('SELECT * FROM shipping_services WHERE id=?',[$id])->fetch():[];if($id&&!$service){http_response_code(404);admin_header('ไม่พบบริการ');admin_footer();exit;}
$value=static function($key,$default='')use($service){return $_SERVER['REQUEST_METHOD']==='POST'?post($key):($service[$key]??$default);};admin_header('บริการขนส่ง');
?>
<p><a href="<?=url('admin/shipping.php')?>">เพิ่มบริการใหม่</a></p><?php if($error): ?><p class="error"><?=e(t($error))?></p><?php endif ?><form method="post" class="panel commerce-admin-form"><?=csrf()?><input type="hidden" name="id" value="<?=$id?>"><?php field('name','ชื่อบริการ/บริษัทขนส่งจริง','text',$value('name'));field('fee','ค่าจัดส่ง (บาท)','text',$value('fee','50.00'));field('free_min','ยอดหลังส่วนลดที่จัดส่งฟรี (เว้นว่าง = ไม่มี)','text',$value('free_min'),false); field('cod_fee','ค่าบริการ COD (บาท)','text',$value('cod_fee','0.00'));field('eta_days','ระยะเวลาจัดส่งโดยประมาณ','text',$value('eta_days'),false);field('max_weight','น้ำหนักสูงสุดที่บริการรองรับ (กก.)','text',$value('max_weight'),false); ?><label>จังหวัดที่รองรับ (จังหวัดละบรรทัด เว้นว่าง = ทุกจังหวัด)<textarea name="provinces" maxlength="10000"><?=e($value('provinces'))?></textarea></label><label class="checkbox"><input type="checkbox" name="cod_allowed" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['cod_allowed']):($service['cod_allowed']??false))?'checked':''?>> บริการนี้รองรับ COD</label><label class="checkbox"><input type="checkbox" name="active" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['active']):($service['active']??false))?'checked':''?>> เปิดใช้งาน</label><button>บันทึกบริการ</button></form>
<div class="table-wrap"><table><tr><th>บริการ</th><th><?=e(t('ค่าจัดส่ง'))?></th><th>ยอดส่งฟรี</th><th>COD</th><th>สถานะ</th></tr><?php foreach(q('SELECT * FROM shipping_services ORDER BY id') as $service): ?><tr><td><a href="?id=<?=$service['id']?>"><?=e($service['name'])?></a></td><td><?=money($service['fee'])?></td><td><?=$service['free_min']===null?'ไม่มี':money($service['free_min'])?></td><td><?=$service['cod_allowed']?'รองรับ':'ไม่รองรับ'?></td><td><?=$service['active']?'เปิด':'ปิด'?></td></tr><?php endforeach ?></table></div><?php admin_footer(); ?>
